import{z as n,x as B,o as l,c as d,q as t,j as i,D as e,d as E,s,S as o,b as A}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"DP-SGD","description":"","frontmatter":{"title":"DP-SGD","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dp-sgd.md","filePath":"llm/dp-sgd.md","lastUpdated":1791413859000}'),D={name:"llm/dp-sgd.md"};function p(m,a,C,h,P,c){const r=B("Mermaid");return l(),d("div",null,[a[2]||(a[2]=t('<h1 id="dp-sgd" tabindex="-1">DP-SGD <a class="header-anchor" href="#dp-sgd" aria-label="Permalink to &quot;DP-SGD&quot;">​</a></h1><div class="epigraph"><p>裁剪再加噪，换的是对单个训练样本的不可区分。预算花完之前，提取变难；预算不是版权许可证。</p><footer>—— Abadi et al., Deep Learning with Differential Privacy；Dwork 差分隐私</footer></div><p><a href="/llm/memorization-copyright">上一课</a>给出可提取的记忆。本课补训练期工具：DP-SGD——对每样本（或每微批）梯度裁剪，再加高斯噪声，用会计追踪 \\((\\varepsilon,\\delta)\\)。缺口不是再讲一遍 AdamW，而是：普通 SGD 对重复样本的梯度可以任意大，DP 把个体影响封顶。后课模型提取是针对已部署接口，不依赖训练是否 DP。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/membership-extraction">成员推断与提取</a> 利用的是「这个样本把参数拽向自己」。差分隐私要求：换掉任意一个样本，输出分布不可区分到 \\(\\varepsilon\\) 级。缺口是把这句话落到大模型微调：全参预训练的 DP 成本极高，实践多在微调、小批次、或 DP-FTRL 变体上。本课只钉 SGD 这一条经典路径。<span class="marginnote">\\((\\varepsilon,\\delta)\\) 是「隐私账单」上的两个数：\\(\\varepsilon\\) 越小，换掉任何一个训练样本后模型输出的变化越小，攻击者越难判断某条记录是否在训练集里；\\(\\delta\\) 是允许的极小失败概率，通常取 \\(10^{-5}\\) 这种比「1 除以数据条数」还小的数。</span></p><p><span class="marginnote">\\(\\varepsilon\\) 小不是「模型不记得语料」。高频模式、公共知识仍在。DP 保护的是个体记录的可证明影响，不是语义遗忘。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每步：算每样本梯度（或用泊松采样的批次），\\(\\ell_2\\) 裁剪到 \\(C\\)，平均后加 \\(\\mathcal{N}(0,\\sigma^2 C^2 I)\\)，再交给优化器。会计（RDP / 矩会计）根据步数、批次、\\(\\sigma\\) 给出 \\(\\varepsilon\\)。超参：过大 \\(C\\) 等于没裁剪；过小 \\(C\\) 加过强噪声，效用崩。语言模型通常先非 DP 预训练，再 DP 微调敏感数据。<span class="marginnote">\\(\\ell_2\\) 裁剪就是「限幅」：把每个样本的梯度向量看成一支箭，长度超过 \\(C\\) 就按比例缩到 \\(C\\)、方向不变。好比会议发言每人限时三分钟——观点还在，但谁也不能靠嗓门大霸占整场讨论。</span></p>',8)),(l(),i(o,null,{default:e(()=>[s(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E6%AF%8F%E6%A0%B7%E6%9C%AC%E6%A2%AF%E5%BA%A6%22%5D%20--%3E%20CLIP%5B%22%E2%84%932%20%E8%A3%81%E5%89%AA%22%5D%0A%20%20CLIP%20--%3E%20NOISE%5B%22%E9%AB%98%E6%96%AF%E5%99%AA%E5%A3%B0%22%5D%0A%20%20NOISE%20--%3E%20ACC%5B%22%E9%9A%90%E7%A7%81%E4%BC%9A%E8%AE%A1%20%CE%B5%22%5D%0A%20%20NOISE%20--%3E%20UPD%5B%22%E5%8F%82%E6%95%B0%E6%9B%B4%E6%96%B0%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("h2",{id:"机制",tabindex:"-1"},[E("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=A("p",null,[E("裁剪限制单个样本对平均梯度的贡献；噪声把剩余贡献淹没到不可区分。组合定理允许很多步，但 \\(\\varepsilon\\) 累积。与 "),A("a",{href:"/llm/memorization-copyright"},"记忆化"),E(" 的关系：DP 降低「因这一条记录而可提取」的可能，不阻止模型生成合法的公共短句。")],-1)),(l(),i(o,null,{default:e(()=>[s(r,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%8D%95%E6%A0%B7%E6%9C%AC%E5%BD%B1%E5%93%8D%E5%A6%82%E4%BD%95%E5%B0%81%E9%A1%B6%22%5D%20--%3E%20C%5B%22%E5%8F%AA%E8%A3%81%E5%89%AA%EF%BC%9A%E6%A2%AF%E5%BA%A6%E6%9C%89%E7%95%8C%E4%BD%86%E4%BB%8D%E6%8C%87%E5%90%91%E8%AF%A5%E6%A0%B7%E6%9C%AC%22%5D%0A%20%20C%20--%3E%20C2%5B%22%E9%87%8D%E5%A4%8D%E5%87%BA%E7%8E%B0%E4%BB%8D%E8%83%BD%E5%A4%9A%E6%AC%A1%E6%8B%89%E6%89%AF%E5%8F%82%E6%95%B0%22%5D%0A%20%20S%20--%3E%20N%5B%22%E5%8F%AA%E5%8A%A0%E5%99%AA%EF%BC%9A%E5%A4%A7%E6%A2%AF%E5%BA%A6%E8%A2%AB%E6%B7%B9%E6%B2%A1%E4%BD%86%E6%96%B9%E5%B7%AE%E5%A4%B1%E6%8E%A7%22%5D%0A%20%20N%20--%3E%20N2%5B%22%E8%A6%81%E4%B9%88%E5%99%AA%E5%A3%B0%E5%A4%A7%E6%AF%81%E6%95%88%E7%94%A8%EF%BC%8C%E8%A6%81%E4%B9%88%E4%BF%9D%E6%8A%A4%E4%B8%8D%E5%A4%9F%22%5D%0A%20%20C2%20--%3E%20BOTH%5B%22%E8%A3%81%E5%89%AA%E5%AE%9A%E4%B8%8A%E9%99%90%20%2B%20%E5%99%AA%E5%A3%B0%E7%9B%96%E8%B4%A1%E7%8C%AE%22%5D%0A%20%20N2%20--%3E%20BOTH%0A%20%20BOTH%20--%3E%20E%5B%22%E5%BE%97%E5%88%B0%E5%8F%AF%E8%AF%81%E6%98%8E%E7%9A%84%20%CE%B5%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>DP 不是版权方案，不是对越狱的防御，也不是校准。效用–隐私曲线在 LLM 上很陡，报告必须同时给下游能力与 \\(\\varepsilon\\)。下一课模型提取假定对手只有 API，即使训练非 DP 也可以蒸馏行为。<span class="marginnote">隐私预算像信用卡额度：每训一步、每加一次噪，会计就刷一笔 \\(\\varepsilon\\)。跳过会计直接训完，你既没法对用户声称任何保护级别，也不知道额度是不是已经刷爆——刷爆之后继续训的步数不再提供任何保证。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DP-SGD：裁剪 + 噪声 + 会计，限制单样本影响。</li><li>实践多在微调；预训练 DP 贵。</li><li>不替代许可与去重。</li><li>出处：Abadi et al. CCS 2016；Dwork 差分隐私。</li></ul>',4))])}const S=n(D,[["render",p]]);export{f as __pageData,S as default};
